using System.Text.RegularExpressions;

namespace Emberfield.Localization
{
    /// <summary>
    /// The game in Spanish (Spain). Screens compose their text in English; composed text is matched by
    /// templates. Text already written in Spanish passes through, apart from a few lines that still name
    /// English buildings or modes. Specific templates come before general ones.
    /// </summary>
    public static class SpanishCatalog
    {
        public static TextTranslator Create()
        {
            var t = new TextTranslator(GameLanguage.Spanish);
            Content(t); Rules(t); Commands(t); Factions(t); Research(t); Hud(t); Naval(t); Menus(t); Settings(t); Guide(t); Online(t); Store(t); Corrections(t);
            return t;
        }

        private static void P(TextTranslator t, params string[] pairs) { for (int i = 0; i + 1 < pairs.Length; i += 2) t.Add(pairs[i], pairs[i + 1]); }
        private static void T(TextTranslator t, params string[] pairs) { for (int i = 0; i + 1 < pairs.Length; i += 2) t.Template(pairs[i], pairs[i + 1]); }

