        private static void Guide(TextTranslator t)
        {
            T(t, "LEARN BY PLAYING / {n:int} OF 9 COMPLETE", "APRENDE JUGANDO / {n} DE 9 COMPLETADOS", "GUIDE  {n:int}/9  ·  {s}", "GUÍA  {n}/9  ·  {s:upper}",
                "Restoring the saved match… {n:int}%", "Restaurando la partida guardada… {n} %");
            P(t,
                "Camera", "Cámara", "Selection", "Selección", "Movement", "Movimiento", "Delivery", "Entrega", "Building", "Construcción",
                "Training", "Entrenamiento", "Attack", "Ataque", "Victory", "Victoria", "Complete", "Completada",
                "GUIDE COMPLETE / 9 OF 9", "GUÍA COMPLETADA / 9 DE 9",
                "The guide is available in Practice and offline AI matches.", "La guía está disponible en la práctica y en las partidas sin conexión contra la IA.",
                "The guide follows your actions. You can stop or restart it from Settings.", "La guía sigue lo que haces. Puedes pararla o reiniciarla desde Ajustes.",
                "Guide paused. Resume keeps completed steps; Start again clears them.", "Guía en pausa. Reanudar conserva los pasos completados; Empezar de nuevo los borra.",
                "The guide is available in Practice and offline AI matches. Your completed steps are saved. Leave this match and return to Practice to continue learning; online play continues while Settings is open.",
                "La guía está disponible en la práctica y en las partidas sin conexión contra la IA. Tus pasos completados se guardan. Sal de esta partida y vuelve a la práctica para seguir aprendiendo; la partida en línea continúa mientras Ajustes está abierto.",
                "Start in Practice to learn camera movement, selection, gathering, building, training, combat and Era progression. Then win a real AI match. The guide remembers completed steps across matches and can be paused any time.",
                "Empieza en la práctica para aprender la cámara, la selección, la recolección, la construcción, el entrenamiento, el combate y el avance de era. Después gana una partida de verdad contra la IA. La guía recuerda los pasos completados entre partidas y puedes pausarla cuando quieras.",
                "Explore the map: pan with the arrow keys, the screen edge or a finger drag. Pinch or use the mouse wheel to zoom.",
                "Explora el mapa: desplázate con las flechas, el borde de la pantalla o arrastrando con el dedo. Pellizca o usa la rueda del ratón para acercar.",
                "Tap one of your workers, or use Workers to select the workers visible on screen.",
                "Toca uno de tus aldeanos o usa Aldeanos para seleccionar los que se ven en pantalla.",
                "With a unit selected, tap open ground and watch it move. Keep Select mode off when giving orders.",
                "Con una unidad seleccionada, toca terreno libre y mira cómo se mueve. Mantén desactivado el modo Selección al dar órdenes.",
                "Select a Tender and tap Food or Wood. Wait for it to carry resources home: only a delivery adds to your stock.",
                "Selecciona un Aldeano y toca comida o madera. Espera a que lleve los recursos a casa: solo lo entregado suma a tus existencias.",
                "Select a Tender, choose Shelter or Muster Hall, tap a clear location and Confirm. Gather more Wood if needed; wait for construction.",
                "Selecciona un Aldeano, elige Casa o Cuartel, toca un lugar despejado y pulsa Confirmar. Recolecta más madera si hace falta y espera a que se construya.",
                "Select your Hearth to train a Tender, or a completed Muster Hall to train a soldier. Keep gathering and wait for the unit to appear.",
                "Selecciona tu Hogar para entrenar un Aldeano o un Cuartel terminado para entrenar un soldado. Sigue recolectando y espera a que aparezca la unidad.",
                "Select a soldier and tap a visible enemy to attack. Train at your Muster Hall if needed; scout to find the rival.",
                "Selecciona un soldado y toca un enemigo visible para atacar. Entrena en tu Cuartel si hace falta y explora para encontrar al rival.",
                "Open Research and advance to the next Era. Meet its building requirements and gather the displayed cost; let research finish.",
                "Abre Investigación y avanza a la era siguiente. Cumple sus requisitos de edificios, reúne el coste indicado y deja que termine la investigación.",
                "Open Play and start an AI match. Win Conquest by destroying every rival Hearth, or Dominion by holding two beacons for eight minutes. This guide continues there.",
                "Abre Jugar y empieza una partida contra la IA. Gana en Conquista destruyendo todos los Hogares rivales, o en Dominio controlando dos faros durante ocho minutos. La guía continúa allí.",
                "Win this match: destroy every rival Hearth in Conquest, or hold two beacons for eight uninterrupted minutes in Dominion. Protect your economy.",
                "Gana esta partida: destruye todos los Hogares rivales en Conquista o controla dos faros durante ocho minutos seguidos en Dominio. Protege tu economía.",
                "Training complete. You explored, gathered, built, trained, attacked, advanced an Era and won a match. Try the other faction or victory condition.",
                "Aprendizaje completado. Has explorado, recolectado, construido, entrenado, atacado, avanzado una era y ganado una partida. Prueba otra facción u otra condición de victoria.");
        }

        private static void Online(TextTranslator t)
        {
            T(t,
                "Server result recorded: {r}. Profile and history refreshed.", "Resultado registrado en el servidor: {r}. Perfil e historial actualizados.",
                "Waiting {n:int}s. Search widens over time.", "Esperando {n} s. La búsqueda se amplía con el tiempo.",
                "Room {c:raw}", "Sala {c:raw}", "Battlefield: {m}", "Campo de batalla: {m}", "Faction: {f}", "Facción: {f}", "Mode: {m}", "Modo: {m}",
