        private static void Store(TextTranslator t)
        {
            T(t,
                "{n:int} APPEARANCES", "{n} APARIENCIAS",
                "{x} preview equipped for offline play. No purchase was made.", "Prueba de {x} equipada para jugar sin conexión. No se ha hecho ninguna compra.");
            P(t,
                "Free alpha previews are for offline play. Listed prices are provisional.", "Las pruebas gratuitas de la alfa son para jugar sin conexión. Los precios son provisionales.",
                "Make your army your own. Every item changes appearance only.", "Haz tuyo tu ejército. Cada objeto solo cambia la apariencia.",
                "Architecture collection", "Colección de arquitectura", "Army appearance", "Apariencia del ejército", "Character skin", "Aspecto de personaje",
                "Offline army appearance restored.", "Apariencia del ejército sin conexión restablecida.",
                "RESET OFFLINE APPEARANCE", "RESTABLECER APARIENCIA SIN CONEXIÓN", "SYNCING…", "SINCRONIZANDO…", "SYNC ONLINE WARDROBE", "SINCRONIZAR VESTUARIO EN LÍNEA",
                "OFFLINE PREVIEW EQUIPPED", "PRUEBA SIN CONEXIÓN EQUIPADA", "TRY FREE IN OFFLINE PLAY", "PROBAR GRATIS SIN CONEXIÓN",
                "EQUIP ALPHA TEST ITEM", "EQUIPAR OBJETO DE PRUEBA ALFA", "EQUIP IN ONLINE WARDROBE", "EQUIPAR EN EL VESTUARIO EN LÍNEA", "PURCHASES OPEN SOON", "COMPRAS DISPONIBLES PRONTO",
                "Sign in through Multiplayer to sync your online wardrobe.", "Inicia sesión en Multijugador para sincronizar tu vestuario en línea.",
                "Online wardrobe synced. Offline previews do not grant paid ownership.", "Vestuario en línea sincronizado. Las pruebas sin conexión no te dan la propiedad de pago.",
                "Online appearance saved for your next room. Combat rules are unchanged.", "Apariencia en línea guardada para tu próxima sala. Las reglas de combate no cambian.");
        }

        // Lines already written in Spanish that still name English buildings or modes.
        private static void Corrections(TextTranslator t)
        {
            P(t,
                "Conquest: destruye los Hearths. Dominion: controla los faros.", "Conquista: destruye los Hogares. Dominio: controla los faros.",
                "Corsario Carmesí: selecciona terreno para moverte o un enemigo para atacar. Héroe de los Piratas; reclutable en su Hearth en Navales.",
                "Corsario Carmesí: selecciona terreno para moverte o un enemigo para atacar. Héroe de los Piratas; se recluta en su Hogar, en Navales.",
                "Tripulación pirata: sable, pistola y exploración. La buscadora recolecta y construye; recluta más en el Hearth y el Muster Hall de los Piratas, en Navales.",
                "Tripulación pirata: sable, pistola y exploración. La buscadora recolecta y construye; recluta más en el Hogar y el Cuartel de los Piratas, en Navales.",
                "ARQUERÍA & DEFENSA", "ARQUERÍA Y DEFENSA", "SABLES, PÓLVORA & EXPLORACIÓN", "SABLES, PÓLVORA Y EXPLORACIÓN");
            // Resource costs such as "50 food 20 wood".
            t.Rule(@"^(?:\d+ (?:food|wood|metal|stone)(?: |$))+$", (m, translate) =>
                Regex.Replace(m.Value, @"\b(food|wood|stone)\b", word => word.Value == "food" ? "comida" : word.Value == "wood" ? "madera" : "piedra"));
        }
    }
